begin;
create view public.financial_attention_alerts with(security_invoker=true) as
select tenant_id,company_id,work_id,'receivable_overdue'::text alert_type,case when days_overdue>30 then 'critical' when days_overdue>7 then 'warning' else 'attention' end severity,'Recebível de medição vencido'::text title,('Contrato '||coalesce(contract_number,'s/n')||' · '||days_overdue||' dia(s) · saldo R$ '||to_char(outstanding_amount,'FM999G999G990D00'))::text detail,due_date reference_date,outstanding_amount reference_amount,measurement_id reference_id from public.engineering_receivables_aging where status in('overdue','partial_overdue')
union all
select tenant_id,company_id,null::uuid,'negative_projected_cash_flow',case when projected_net_flow<0 then 'critical' else 'warning' end,'Fluxo de caixa projetado negativo',('Competência '||to_char(competence,'MM/YYYY')||' · saldo projetado R$ '||to_char(projected_net_flow,'FM999G999G990D00')),competence,projected_net_flow,null::uuid from public.projected_cash_flow where projected_net_flow<0
union all
select tenant_id,company_id,work_id,'high_receivables_risk',case when overdue_percent>=50 then 'critical' else 'warning' end,'Inadimplência elevada na obra',('Atraso '||overdue_percent||'% · vencido R$ '||to_char(overdue_total,'FM999G999G990D00')),current_date,overdue_total,work_id from public.engineering_receivables_risk_dashboard where overdue_total>0 and overdue_percent>=20;
create view public.financial_attention_summary with(security_invoker=true) as select tenant_id,company_id,count(*) alert_count,count(*) filter(where severity='critical') critical_count,count(*) filter(where severity='warning') warning_count,count(*) filter(where severity='attention') attention_count,coalesce(sum(abs(reference_amount)) filter(where alert_type='receivable_overdue'),0)::numeric(18,2) overdue_receivables,coalesce(sum(abs(reference_amount)) filter(where alert_type='negative_projected_cash_flow'),0)::numeric(18,2) projected_cash_deficit from public.financial_attention_alerts group by tenant_id,company_id;
commit;